193		// 学生历史中没有这份新修读；已保存的修读 e1 保持选课，记录文件原样不变，
194		// 核对仍为 0 学分、r1 未满足。
195		assertRecordUnchanged(t, file, before, "停开后新增修读被拒绝：")
196		show, _, _ := runCLI(t, file, "show", "s1")
197		if strings.Contains(show, "修读 e2") ||
198			!strings.Contains(show, "修读 e1：要求 r1，学期 2024春，结果：选课") {
199			t.Fatalf("历史中不应出现新修读 e2，e1 应保持选课，out=%q", show)
200		}
201		out, _, code = runCLI(t, file, "check", "s1")
202		if code != 0 || !strings.Contains(out, "总学分：0") ||
203			!strings.Contains(out, "未满足要求：[r1]") {
204			t.Fatalf("拒绝新增后应仍为 0 学分、r1 未满足，code=%d out=%q", code, out)
205		}
206	
207		// 这次拒绝不能影响随后为另一份停开前已登记、仍处于选课状态的修读提交成绩。
208		out, errText, code = runCLI(t, file, "pass", "s1", "e1")
209		if code != 0 || !strings.Contains(out, "修读 e1 结果已提交：通过") {
210			t.Fatalf("拒绝新增后仍应为旧修读 e1 提交通过，code=%d out=%q err=%q",
211				code, out, errText)
212		}
213		out, _, code = runCLI(t, file, "check", "s1")
214		if code != 0 || !strings.Contains(out, "总学分：4") ||
215			!strings.Contains(out, "已满足，来源为通过修读 e1") ||
216			strings.Contains(out, "未满足要求：[") {
217			t.Fatalf("旧修读 e1 提交通过后应满足 r1、计 4 学分，code=%d out=%q", code, out)
218		}
219		show, _, _ = runCLI(t, file, "show", "s1")
220		if !strings.Contains(show, "修读 e1：要求 r1，学期 2024春，结果：通过") ||
221			strings.Contains(show, "修读 e2") {
222			t.Fatalf("e1 应变为通过，历史中仍不应有被拒绝的 e2，out=%q", show)
223		}
224	
225		// 新增修读被禁止的规则在提交成绩后仍然有效，与“旧修读可以提交成绩”并存。
226		_, errText, code = runCLI(t, file, "enroll", "s1", "r1", "2025春", "e3")
227		if code != 1 || !strings.Contains(errText, "课程 c1 已停开，不能新增修读") {
228			t.Fatalf("提交成绩后新增修读仍应被拒绝并指出停开，code=%d err=%q", code, errText)
229		}
230		if show, _, _ := runCLI(t, file, "show", "s1"); strings.Contains(show, "修读 e3") {
231			t.Fatalf("再次拒绝后历史中不应出现 e3，out=%q", show)
232		}
233	}
